"use client";

import * as React from "react";
import { Menu as MenuPrimitive } from "@base-ui/react/menu";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

type PositionerProps = Pick<MenuPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

/** The menu panel: the white floating panel, at least 12rem wide, padded 0.25rem. */
const menuPanel = cn(popoverSurface, popupMotion, "min-w-48 max-h-(--available-height) overflow-y-auto p-1");

/** Margin DropdownMenu root: a list of actions behind one trigger. */
const DropdownMenu = MenuPrimitive.Root;

/** The control the menu opens from. */
const DropdownMenuTrigger = MenuPrimitive.Trigger;

/** Groups related rows and gives a label something to name. */
const DropdownMenuGroup = MenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const DropdownMenuPortal = MenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const DropdownMenuSub = MenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const DropdownMenuRadioGroup = MenuPrimitive.RadioGroup;

/** Margin menu panel: a white panel with a hairline and a soft drop, growing from the trigger. */
function DropdownMenuContent({
  className,
  align = "start",
  alignOffset,
  side,
  sideOffset = 6,
  ...props
}: WithClassName<MenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup data-slot="dropdown-menu-content" className={cn(menuPanel, className)} {...props} />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  );
}
DropdownMenuContent.displayName = "DropdownMenuContent";

/** A nested menu panel that opens beside its row, level with the row's top. */
function DropdownMenuSubContent({
  className,
  align = "start",
  alignOffset = -4,
  side = "right",
  sideOffset = 4,
  ...props
}: WithClassName<MenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup data-slot="dropdown-menu-sub-content" className={cn(menuPanel, className)} {...props} />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  );
}
DropdownMenuSubContent.displayName = "DropdownMenuSubContent";

/**
 * A menu row, 2rem tall, that turns field grey under the pointer or keyboard.
 * The destructive variant turns the text red with a faint red wash.
 */
function DropdownMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: WithClassName<MenuPrimitive.Item.Props> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <MenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-variant={variant}
      className={cn(
        menuItemBase,
        variant === "destructive" &&
          "text-destructive-text data-[highlighted]:bg-destructive/10 data-[highlighted]:text-destructive-text [&_svg]:text-current",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
DropdownMenuItem.displayName = "DropdownMenuItem";

/** A row that opens a nested menu, with a caret at the end. */
function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: WithClassName<MenuPrimitive.SubmenuTrigger.Props> & { inset?: boolean }) {
  return (
    <MenuPrimitive.SubmenuTrigger
      data-slot="dropdown-menu-sub-trigger"
      className={cn(
        menuItemBase,
        "data-[popup-open]:bg-(--field) data-[popup-open]:text-accent-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      <Icon icon="solar:alt-arrow-right-linear" className="ms-auto rtl:rotate-180" aria-hidden="true" />
    </MenuPrimitive.SubmenuTrigger>
  );
}
DropdownMenuSubTrigger.displayName = "DropdownMenuSubTrigger";

/** A row that toggles on and off, with an oxblood tick at the start when on. */
function DropdownMenuCheckboxItem({
  className,
  children,
  ...props
}: WithClassName<MenuPrimitive.CheckboxItem.Props>) {
  return (
    <MenuPrimitive.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <MenuPrimitive.CheckboxItemIndicator>
          <Icon icon="solar:unread-linear" className="text-(--primary-text)!" aria-hidden="true" />
        </MenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </MenuPrimitive.CheckboxItem>
  );
}
DropdownMenuCheckboxItem.displayName = "DropdownMenuCheckboxItem";

/** One choice in a radio group, with a small oxblood dot at the start when chosen. */
function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: WithClassName<MenuPrimitive.RadioItem.Props>) {
  return (
    <MenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <MenuPrimitive.RadioItemIndicator>
          <span className="block size-1.5 rounded-full bg-primary" />
        </MenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </MenuPrimitive.RadioItem>
  );
}
DropdownMenuRadioItem.displayName = "DropdownMenuRadioItem";

/** A small muted heading over a group of rows, used inside a group. */
function DropdownMenuLabel({
  className,
  inset,
  ...props
}: WithClassName<MenuPrimitive.GroupLabel.Props> & { inset?: boolean }) {
  return (
    <MenuPrimitive.GroupLabel
      data-slot="dropdown-menu-label"
      className={cn("px-2.5 py-1.5 text-xs font-medium text-muted-foreground", inset && "ps-8", className)}
      {...props}
    />
  );
}
DropdownMenuLabel.displayName = "DropdownMenuLabel";

/** A hairline between groups that runs to the panel's edges. */
function DropdownMenuSeparator({ className, ...props }: WithClassName<MenuPrimitive.Separator.Props>) {
  return (
    <MenuPrimitive.Separator
      data-slot="dropdown-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}
DropdownMenuSeparator.displayName = "DropdownMenuSeparator";

/** The keyboard shortcut at the end of a row, in small muted type. */
function DropdownMenuShortcut({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn("ms-auto ps-4 text-xs text-muted-foreground", className)}
      {...props}
    />
  );
}
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

export {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuGroup,
  DropdownMenuPortal,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuRadioGroup,
};
